query:
query ($owner: String!, $repo: String!, $prefix: String!, $contains: String!, $first: Int!, $after: String) {
  repository(owner: $owner, name: $repo) {
    branchCount: refs(refPrefix: $prefix, first: 0) { totalCount }
    branches: refs(refPrefix: "refs/heads/", query: $contains, first: $first, after: $after, orderBy: {field: ALPHABETICAL, direction: ASC}) {
      pageInfo { hasNextPage endCursor }
      nodes {
        name
        associatedPullRequests(states: OPEN, first: 10) {
          pageInfo { hasNextPage }
          nodes {
            number
            url
            body
            headRefName
            headRepository { nameWithOwner }
            repository { nameWithOwner }
            author { login }
            labels(first: 100) { pageInfo { hasNextPage } nodes { name } }
          }
        }
      }
    }
  }
}
